import {workshops,portfolioRubric} from './data/workshops.js';
import {missionKey,missionStatus} from './workshop-state.js';
import {escapeHTML as e} from './state.js';

const url=(w,m)=>`#/projects/workshop-${w.id}${m?'/'+m.id:''}`;
const done=(w,state)=>w.milestones.filter(m=>missionStatus(w,m,state).reviewed).length;
export function workshopCatalog(state){
 const core=workshops.filter(w=>w.core),hours=core.reduce((n,w)=>n+w.hours,0);
 return `<section class="workshop-catalog" id="workshop-catalog"><div class="page-heading"><div><span class="eyebrow">10 PROJECTS · 50 MILESTONES</span><h2>完整项目工作坊：把机制连接成作品</h2><p>原有 16 关负责机制入门；这里按项目完成数据、实现、训练、评测、优化与答辩。</p></div></div><section class="panel panel-pad workshop-budget"><h3>核心路径与时间预算</h3><p>7 个核心项目约 ${hours} 小时，配合约 20 小时机制练习与补课，三个月约每周 10–11 小时。只用每天半小时通常需要延长周期。3 个扩展项目再预留 ${workshops.filter(w=>!w.core).reduce((n,w)=>n+w.hours,0)} 小时，不挤占核心验收。</p><p>建议顺序：P01 → P06 → P02 → P04 → P07 → P09 → P10；P03、P05、P08 按兴趣或岗位要求扩展。时间是练习预算，GPU 排队、下载与真实问题调试可能更久。</p><p class="small">完成命令只是起点。每个项目都要有你亲手实现的部分、受控实验、失败解释和可复核交付。下方进度是学习者自查，不是自动就业认证。</p></section><div class="workshop-card-grid">${workshops.map(w=>`<a class="panel workshop-card" href="${url(w)}"><div class="between"><span class="eyebrow">${w.number} · ${w.core?'核心作品':'扩展专题'}</span><span class="badge">${done(w,state)}/${w.milestones.length} 自查</span></div><h3>${e(w.title)}</h3><p>${e(w.summary)}</p><p class="small muted">${e(w.scope)}</p><div class="between"><span class="small">约 ${w.hours} 小时 · 第 ${e(w.weeks)} 周</span><span class="text-link">进入带练 →</span></div></a>`).join('')}</div><section class="panel panel-pad workshop-portfolio"><h2>转岗作品自评：每项都附证据</h2><p>选最接近你当前真实能力的一档，再写下代码、测试或实验报告的位置。分数不加总成“录用概率”；任何薄弱项都应转成下一次任务。</p>${portfolioRubric.map(r=>{const saved=state.portfolio?.[r.id]||{};return `<div class="portfolio-row"><label for="rubric-${r.id}"><b>${e(r.title)}</b></label><select class="field portfolio-score" id="rubric-${r.id}" data-rubric="${r.id}"><option value="">尚未自评</option>${r.levels.map((label,i)=>`<option value="${i}" ${saved.score===i?'selected':''}>${i} · ${e(label)}</option>`).join('')}</select><label class="sr-only" for="rubric-evidence-${r.id}">${e(r.title)}的证据</label><textarea class="field portfolio-evidence" id="rubric-evidence-${r.id}" data-rubric="${r.id}" rows="2" placeholder="例如：哪份代码是你写的，哪个对照支持结论，哪里仍不会">${e(saved.evidence||'')}</textarea></div>`}).join('')}<p class="small muted" id="portfolio-status">自评与证据仅存本机，可随学习备份导出。</p></section></section>`;
}

export function missionCompletion(workshop,mission,state){
 const status=missionStatus(workshop,mission,state);
 return `<div class="between wrap"><div><h3>${status.reviewed?'本里程碑已记录自查':'本里程碑的证据检查'}</h3><p>交付物 ${status.count}/${mission.evidence.length} · ${status.hasEvidence?'已写观察记录':'请写至少 30 个字符的实际观察'}</p></div><button class="btn btn-primary" data-action="workshop-review" data-workshop="${workshop.id}" data-mission="${mission.id}" ${status.ready?'':'disabled'}>保存本次自查</button></div><p class="small muted">文本长度与勾选只确保你留下记录，不判断实验真实性或算法正确性。代码检查、指标和答辩需要独立验证。</p>`;
}

export function workshopPage(workshop,missionId,state){
 const mission=workshop.milestones.find(m=>m.id===missionId)||workshop.milestones.find(m=>!missionStatus(workshop,m,state).reviewed)||workshop.milestones[0];
 const index=workshop.milestones.indexOf(mission),record=state.workshopProgress?.[missionKey(workshop,mission)]||{};
 return `<div class="project-breadcrumb"><a href="#/projects">项目实战</a><span> / ${workshop.number} · ${e(workshop.title)}</span></div><div class="page-heading"><div><span class="eyebrow">${workshop.core?'核心作品':'扩展专题'} · 约 ${workshop.hours} 小时 · ${workshop.milestones.length} 个里程碑</span><h1>${e(workshop.title)}</h1><p>${e(workshop.summary)}</p></div></div><section class="panel panel-pad workshop-intro"><h2>这个项目要让你具备什么能力</h2>${workshop.intro.map(p=>`<p class="project-prose">${e(p)}</p>`).join('')}<p class="callout"><b>当前可运行范围：</b>${e(workshop.scope)}</p><ol class="workshop-pipeline" aria-label="项目数据流">${workshop.pipeline.map(item=>`<li>${e(item)}</li>`).join('')}</ol><details open><summary>先认识本项目的三个关键词</summary><dl>${workshop.terms.map(([name,meaning])=>`<dt>${e(name)}</dt><dd>${e(meaning)}</dd>`).join('')}</dl></details><details><summary>代码地图：从哪个函数读起</summary><div class="table-wrap"><table><thead><tr><th>文件与入口</th><th>这一步解决什么</th></tr></thead><tbody>${workshop.files.map(([path,symbol,role])=>`<tr><td><a class="text-link" href="https://github.com/TatenLee/model-craft/blob/main/${e(path)}" target="_blank" rel="noopener noreferrer">${e(path)}</a><br><code>${e(symbol)}</code></td><td>${e(role)}</td></tr>`).join('')}</tbody></table></div></details><div class="row wrap space-top"><a class="btn" href="./downloads/model-craft-projects.zip" download>下载源码、学生代码与运行指南</a>${workshop.prerequisites.map(id=>`<a class="btn btn-small" href="#/projects/${id}">补机制：${e(id)}</a>`).join('')}</div></section>
 <div class="workshop-layout"><aside class="panel workshop-nav"><h3>按里程碑推进</h3>${workshop.milestones.map((m,i)=>`<a class="${m.id===mission.id?'active':''}" href="${url(workshop,m)}" ${m.id===mission.id?'aria-current="step"':''}><span>${missionStatus(workshop,m,state).reviewed?'✓':String(i+1).padStart(2,'0')}</span>${e(m.title)}</a>`).join('')}<p class="small muted">一次 30 分钟可以只做一个操作；训练、排错、记录可拆到不同天。换页会保存记录。</p></aside><div class="stack"><section class="panel panel-pad workshop-mission"><span class="eyebrow">MILESTONE ${index+1} / ${workshop.milestones.length}</span><h2>${e(mission.title)}</h2><h3>先理解：为什么做这一步</h3><p class="project-prose">${e(mission.why)}</p><h3>今天按这个顺序做</h3><ol class="workshop-actions">${mission.actions.map(action=>`<li>${e(action)}</li>`).join('')}</ol><h3>从这里运行或检查</h3><p class="small">在仓库根目录激活 Python 环境。首次准备步骤见下载包 projects/README.md；所有实验输出留在 .openai/local/。</p><pre><code>${e(mission.command)}</code></pre><p class="small">命令是当前步骤的入口，动作清单可能还要求你修改临时分支、重复对照或读取代码。只执行一次命令不能替代这些工作。</p><h3>应该看到什么</h3><p>${e(mission.expected)}</p><h3>不符合预期时，先查哪里</h3><p>${e(mission.debug)}</p></section>
 <section class="panel panel-pad"><h2>暂停一下，先自己解释</h2><p class="project-prose">${e(mission.question)}</p><details class="workshop-answer"><summary>展开参考分析，再核对你的解释</summary><p>${e(mission.answer)}</p><p class="small muted">能复述答案还不够，请用你自己的代码、样本或实验结果说明。</p></details></section>
 <section class="panel panel-pad"><h2>本次实际证据</h2><p>按“假设 → 改了什么 → 命令/版本 → 实际结果 → 解释/下一步”记录。没有做的实验明确写待做，勿把教程样例当成自己的结果。</p><label for="workshop-note">实验与疑问记录</label><textarea class="field workshop-note" id="workshop-note" data-workshop="${workshop.id}" data-mission="${mission.id}" rows="9" maxlength="6000" placeholder="例如：我固定 seed 和数据，只改变……；预期……；实际报告……；可能原因……；下一步只验证……">${e(record.note||'')}</textarea><p class="small muted" id="workshop-note-status">记录只在本机保存，导出学习备份可保留。</p><fieldset class="workshop-evidence"><legend>我已准备好以下交付物（自报）</legend>${mission.evidence.map((item,i)=>`<label><input type="checkbox" class="workshop-check" data-workshop="${workshop.id}" data-mission="${mission.id}" value="${i}" ${record.checked?.includes(i)?'checked':''}><span>${e(item)}</span></label>`).join('')}</fieldset><div id="workshop-completion">${missionCompletion(workshop,mission,state)}</div><button class="btn" data-action="workshop-export" data-workshop="${workshop.id}" data-mission="${mission.id}">下载带练交接单</button><hr><h3>在页面查看本地实验报告</h3><p class="small">支持微型语言模型 .metrics.json、world-lab、SFT 和 advanced-labs 报告，仅在本页内存显示，不上传、不自动判分。</p><label class="btn">选择 report.json<input type="file" id="workshop-report-file" accept=".json,application/json"></label><div id="workshop-report-result" aria-live="polite"></div></section>
 <section class="panel panel-pad"><h2>整个项目必须做的对照</h2><div class="table-wrap"><table><thead><tr><th>比较什么</th><th>怎样让结论可信</th></tr></thead><tbody>${workshop.compare.map(([title,body])=>`<tr><td>${e(title)}</td><td>${e(body)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel panel-pad"><h2>最终答辩：别人会继续追问什么</h2><ol class="workshop-actions">${workshop.defense.map(q=>`<li>${e(q)}</li>`).join('')}</ol><p>答案需指出你亲自实现的文件、你做的对照和结论边界。无法回答的条目留在交接单中，作为下一轮带练入口。</p><div class="row wrap">${workshop.sources.map(s=>`<a class="source-link" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a>`).join('')}</div></section><div class="between wrap">${index>0?`<a class="btn" href="${url(workshop,workshop.milestones[index-1])}">← 上一里程碑</a>`:'<a class="btn" href="#/projects">返回项目地图</a>'}${index<workshop.milestones.length-1?`<a class="btn btn-primary" href="${url(workshop,workshop.milestones[index+1])}">下一里程碑 →</a>`:'<a class="btn btn-primary" href="#/projects">返回作品自评 →</a>'}</div></div></div>`;
}

export function workshopReportHTML(raw){
 if(Array.isArray(raw)){
  if(!raw.length||raw.length>500||raw.some(r=>!r||!Number.isInteger(r.step)||r.step<0||typeof r.validation_loss!=='number'||!Number.isFinite(r.validation_loss)||r.validation_loss<0))throw new Error('语言模型指标文件格式无效。');
  const rows=raw.map(r=>({step:r.step,validation_loss:r.validation_loss,validation_perplexity:r.validation_perplexity,token_accuracy:r.token_accuracy}));
  const text=JSON.stringify(rows,null,2);if(text.length>30000)throw new Error('报告指标部分过大。');
  return `<div class="callout"><b>已读取：微型语言模型指标（学习者提供）</b><p>这是报告中的原始观察，不是训练真实性认证；读取不会改变自查状态。</p><pre>${e(text)}</pre></div>`;
 }
 const names={'model-craft-world-v1':'世界模型','model-craft-sft-v1':'SFT / LoRA','model-craft-advanced-v1':'进阶实验'};
 if(!raw||!names[raw.schema])throw new Error('请选择课程脚本产生的 report.json。');
 const keys=['experiment','scope','before','validation','metrics','position_mse','zero_position_baseline','before_velocity_mse','validation_velocity_mse','left_mode_fraction','fraction_within_0_75_of_a_mode','cache_max_abs_error','cache_bytes','weight_fp32_bytes','int8_plus_scale_bytes','weight_max_abs_error','timing','feature_dim','trainable_parameters','parameters','step','steps','checkpoint_step'];
 const result=Object.fromEntries(keys.filter(k=>raw[k]!==undefined).map(k=>[k,raw[k]]));
 const text=JSON.stringify(result,null,2);if(text.length>30000)throw new Error('报告指标部分过大，请检查格式。');
 return `<div class="callout"><b>已读取：${names[raw.schema]}（学习者提供）</b><p>以下是报告中的原始指标，不代表平台已验证训练发生。请解释 split、单位、基线和失败样例；报告读取不会改变自查状态。</p><pre>${e(text)}</pre></div>`;
}
